import asyncio
from collections import Counter

async def get_all_metformin_forms():
    all_titles = []
    for page in range(1, 6):  # Get first 5 pages (50 records)
        r = await request("dailymed", "/spls.json", {
            "drug_name": "metformin",
            "pagesize": 10,
            "page": page
        })
        if "data" in r and "data" in r["data"] and r["data"]["data"]:
            for item in r["data"]["data"]:
                title = item.get("title", "")
                # Extract dosage form from title
                if "TABLET" in title:
                    idx = title.find("TABLET")
                    if idx != -1:
                        form_part = title[idx+7:].strip()  # After "TABLET"
                        # Remove manufacturer name (in brackets)
                        if "[" in form_part:
                            form_part = form_part[:form_part.index("[")]
                        all_titles.append(form_part)
                elif "SOLUTION" in title:
                    all_titles.append("SOLUTION")

    # Count occurrences and group similar forms
    counts = Counter(all_titles)

    # Clean up the data - remove trailing spaces and group similar forms
    cleaned_counts = {}
    for form, count in counts.items():
        clean_form = form.strip()
        if clean_form not in cleaned_counts:
            cleaned_counts[clean_form] = 0
        cleaned_counts[clean_form] += count

    # Sort by count descending, take top 3
    sorted_forms = sorted(cleaned_counts.items(), key=lambda x: x[1], reverse=True)[:3]
    return sorted_forms

result = asyncio.run(get_all_metformin_forms())
print(result)

