    dosage_forms = []
    for item in data:
        title = item["title"]
        # Look for patterns like "TABLET", "SOLUTION", etc.
        # The dosage form is usually after the drug name and before any strength info
        # Common patterns: "TABLET, FILM COATED", "EXTENDED RELEASE", "SOLUTION"

        # Remove common prefixes
        clean_title = title.lower()

        # Check for solution first (usually at the end or near the beginning)
        if "solution" in clean_title and "tablet" not in clean_title:
            dosage_forms.append("SOLUTION")
        elif "capsule" in clean_title:
            dosage_forms.append("CAPSULE")
        elif "injection" in clean_title:
            dosage_forms.append("INJECTION")
        else:
            # It's likely a tablet, but let's check for extended release vs immediate release
            if "extended release" in clean_title or "er" in clean_title:
                dosage_forms.append("TABLET EXTENDED RELEASE")
            elif "film coated" in clean_title:
                dosage_forms.append("TABLET FILM COATED")
            elif "coated" in clean_title and "film" not in clean_title:
                dosage_forms.append("TABLET COATED")
            else:
                # Default to tablet if it contains "tablet"
                if "tablet" in clean_title:
                    dosage_forms.append("TABLET")
                else:
                    # Try to extract what we can
                    parts = title.split(", ")
                    for part in parts:
                        if any(x in part.lower() for x in ["tablet", "capsule", "solution", "injection"]):
                            if "extended release" in part.lower():
