        batch_size = 200
        verified_count = 0

        for i in range(0, len(pmids), batch_size):
            batch_pmids = pmids[i:i+batch_size]
            summary_r = await request("pubmed", "/esummary.fcgi", {
                "id": ",".join(batch_pmids)
            })

            result_data = summary_r["data"]["result"]

            # Check the type of result_data
            print(f"Batch {i//batch_size}: result_data type = {type(result_data)}")
            if isinstance(result_data, dict):
                print(f"  Keys: {list(result_data.keys())[:5]}...")
                for pmid_str in list(result_data.keys())[:3]:
                    summary = result_data[pmid_str]
                    print(f"  PMID {pmid_str}: summary type = {type(summary)}, keys = {summary.keys() if isinstance(summary, dict) else 'N/A'}")
            elif isinstance(result_data, list):
                print(f"  Length: {len(result_data)}")
                for item in result_data[:3]:
                    print(f"  Item type = {type(item)}, keys = {item.keys() if isinstance(item, dict) else 'N/A'}")

            # Process the data
            if isinstance(result_data, dict):
                for pmid_str, summary in result_data.items():
                    pubdate = summary.get("pubdate", "")
                    if pubdate:
                        year = pubdate.split("/")[0] if "/" in pubdate else pubdate
                        if year in ["2024", "2025"]:
                            verified_count += 1
            elif isinstance(result_data, list):
                for item in result_data:
                    pubdate = item.get("pubdate", "") if isinstance(item, dict) else ""
                    if pubdate:
                        year = pubdate.split("/")[0] if "/" in pubdate else pubdate
                        if year in ["2024", "2025"]:
                            verified_count += 1

        print(f"Verified count from summaries: {verified_count}")

    return total_count, verified_count

